function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function modal(title,body){$('#dialog-content').innerHTML=`<h2>${e(title)}</h2>${body}`;$('#dialog').showModal();}
function list(type){return applyLibraryOverrides(type,[...builtinResources(type),...(store.get()[type]||[]).map(x=>({...x,library_source:'personal'})),...(remote[type]||[])]).filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i);}
function button(text,to,cls=''){return `<button class="btn ${cls}" data-route="${to}">${text} ${icon('arrow')}</button>`;}
function heading(title,description,action=''){return `<div class="heading"><div><span class="eyebrow">${copyHTML("app.6bafe4bf2ff1")}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function empty(title,text,action=''){return `<div class="empty"><div class="empty-icon">§</div><h3>${title}</h3><p>${text}</p>${action}</div>`;}
function toolbar(type){return `<div class="toolbar"><input id="search" aria-label="Search ${type}" placeholder="Search ${type}…" value="${e(filter)}"><select id="subject" aria-label="${copyHTML("app.599830592f43")}">${subjectCatalog.filters().map(s=>`<option ${s===subject?'selected':''}>${e(s)}</option>`).join('')}</select></div>`;}
function filtered(items){return items.filter(x=>(subject==='All subjects'||x.subject===subject)&&`${x.title||x.name||x.front} ${x.description||''} ${x.subject||''}`.toLowerCase().includes(filter.toLowerCase()));}
function today(){return new Date().toLocaleDateString('en-CA');}
function minutes(){return store.get().sessions.reduce((s,x)=>s+x.minutes,0);}
function score(){const a=store.get().attempts;return a.length?Math.round(a.reduce((s,x)=>s+x.score/x.total_questions*100,0)/a.length):0;}
function stats(){const s=store.get();return `<div class="stats">${[[s.completed.length,copyRaw("app.dfdf6a2a7777"),copyRaw("app.3a55c190249b"),'materials'],[s.attempts.length,copyRaw("app.b5091ec027e9"),s.attempts.length?`${score()}% average score`:copyRaw("app.ada33714cb99"),'quiz'],[minutes(),copyRaw("app.36e40f0394ea"),copyRaw("app.8f244c99cbe3"),'study'],[s.bookmarks.length,copyRaw("app.5d702bc5a04d"),copyRaw("app.7c542559b5f0"),'bookmark']].map(([n,t,sub,i])=>`<div class="stat"><span class="stat-icon">${icon(i)}</span><div><small>${t}</small><strong>${n}</strong><span class="sub">${sub}</span></div></div>`).join('')}</div>`;}
function dashboard(){const s=store.get();const tasks=s.tasks;return heading(`${copyRaw("app.794dd849406a")}${e(s.profile.name.split(' ')[0])}.`,copyRaw("app.f8c70a6d6247"),`<span class="date">${icon('calendar')}${new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}</span>`)+`<section class="hero"><div><span class="eyebrow">${copyHTML("app.d80606ad1927")}</span><h2>${copyHTML("app.f49cc4cd9bf8")}<br>${copyHTML("app.a439a11f69a2")}</h2><p>${copyHTML("app.e746623544a1")}</p>${button(copyRaw("app.bbc4fcc42c68"),'study')}</div><div class="hero-art" aria-hidden="true"><span>§</span></div></section>${stats()}<div class="dashboard-grid"><div><section class="card"><div class="card-head"><div><h2>${copyHTML("app.d4d436143f9f")}</h2><p>${copyHTML("app.d65f9616ea0f")}</p></div><button class="text-button" data-route="materials">${copyHTML("app.11d193016475")}</button></div>${list('materials').slice(0,3).map((m,i)=>`<div class="row"><span class="row-icon">${['▤','▥','▧'][i]}</span><div class="row-copy"><strong>${e(m.title)}</strong><small>${e(m.subject)} <span class="dot">·</span> ${e(m.type||'Resource')}</small></div><button class="btn" data-open-material="${e(m.id)}">${s.completed.includes(m.id)?copyRaw("app.81033ad744f4"):copyRaw("app.9b9a8d05a7ec")} ↗</button></div>`).join('')}</section><section class="card" style="margin-top:22px"><div class="card-head"><h2>${copyHTML("app.3716eb9d9050")}</h2><button class="text-button" data-route="lectures">${copyHTML("app.93446272bee5")}</button></div>${recordings().length?recordingRows(recordings().slice(0,3)):`<p class="muted">${copyHTML("app.0c0430233748")}</p>`}</section><div class="section-title"><h2>${copyHTML("app.f9e086c14f01")}</h2><span class="muted">${copyHTML("app.61118b1d8aa7")}</span></div><div class="quick-grid">${[['quiz',copyRaw("app.2a2499f1f86d"),copyRaw("app.aeb79837c0bd")],['cases',copyRaw("app.e66b5210259e"),copyRaw("app.0beb0ae81443")],['flashcards',copyRaw("app.57490bdb4451"),copyRaw("app.4eab97d83dd8")]].map(([r,t,d])=>`<button class="quick" data-route="${r}">${icon(r)}<strong>${t}</strong><small>${d}</small></button>`).join('')}</div></div><div><section class="card"><div class="card-head"><h2>${copyHTML("app.5d93e45505fb")}</h2><span class="pill">${tasks.filter(t=>t.done).length}/${tasks.length}</span></div><p class="muted">${copyHTML("app.01873311a672")}</p><div>${tasks.length?tasks.map(t=>`<label class="task ${t.done?'completed':''}"><input type="checkbox" data-task="${e(t.id)}" ${t.done?'checked':''}><span>${e(t.text)}</span><button class="remove-task" data-remove-task="${e(t.id)}" aria-label="${copyHTML("app.9ada6a712243")}">×</button></label>`).join(''):`<p class="muted">${copyHTML("app.0670599ad20e")}</p>`}</div><form id="task-form" class="task-add"><input name="task" required maxlength="160" placeholder="${copyHTML("app.eb35e44559c2")}" aria-label="${copyHTML("app.070ff669b4cf")}"><button class="btn soft" aria-label="${copyHTML("app.ba423a46403c")}">+</button></form></section><section class="focus-mini"><span class="eyebrow">${copyHTML("app.4584a717525b")}</span><h3>${copyHTML("app.932e868a45a6")}</h3><p>${copyHTML("app.4848d3a538c0")}</p>${button(copyRaw("app.49e43084e793"),'study','primary')}</section></div></div>`;}
function readingItems(){return [...list('materials').map(x=>({...x,resource_type:'materials'})),...list('lectureNotes').map(x=>({...x,resource_type:'lectureNotes'}))];}
function recordings(){return (remote.lectures||[]).filter(isAudioRecording);}
function materials(){return heading(copyRaw("app.fda5ba71a49b"),copyRaw("app.6487e81ae907"))+`<div class="admin-tabs">${[['all',copyRaw("app.dd036462e6ce")],['materials',copyRaw("app.fd10a146e962")],['lectureNotes',copyRaw("app.cf0659e6a0e1")]].map(([kind,label])=>`<button class="btn ${materialKind===kind?'primary':''}" data-reading-kind="${kind}">${label}</button>`).join('')}</div>`+toolbar('materials and lecture notes')+`<div class="grid" id="results">${materialCards()}</div>`;}

function materialCards(){const state=store.get(),items=filtered(readingItems()).filter(x=>materialKind==='all'||x.resource_type===materialKind);return items.length?items.map(m=>`<article class="card resource"><div class="resource-top"><span class="tag">${e(m.subject||'General')}</span><button class="icon-button" data-bookmark="${e(m.id)}" aria-label="${state.bookmarks.includes(m.id)?copyRaw("app.51883bd8df17"):copyRaw("app.1509f561f241")} ${e(m.title)}">${state.bookmarks.includes(m.id)?'◆':'◇'}</button></div><h3>${e(m.title)}</h3><p>${e(m.description||'Course resource')}</p><span class="muted">${m.resource_type==='lectureNotes'?copyRaw("app.8e8dd2dc8d4d"):copyRaw("app.616cb218a65b")}</span><div class="actions"><button class="btn primary" data-open-resource="${m.resource_type}:${e(m.id)}">${copyHTML("app.3ece59baa50c")}</button><button class="btn" data-download-resource="${m.resource_type}:${e(m.id)}">${copyHTML("app.fcc51ef8e95b")}</button>${state.completed.includes(m.id)?`<span class="tag">${copyHTML("app.8df25e6373a6")}</span>`:''}</div></article>`).join(''):empty(copyRaw("app.fee1b1255e1d"),copyRaw("app.7958b2e60420"));}

function recordingRows(items){return items.map(record=>`<div class="row"><span class="row-icon">♫</span><div class="row-copy"><strong>${e(record.title)}</strong><small>${e(record.subject)} ${copyHTML("app.820a00916073")}</small></div><button class="btn primary" data-play-recording="${e(record.id)}" aria-pressed="false">${copyHTML("app.b3b60a22a04f")}</button></div>`).join('');}
function lectures(){const items=filtered(recordings());return heading(copyRaw("app.95f7caf5f942"),copyRaw("app.9a66ded3582a"))+toolbar('lecture recordings')+`<div id="results" class="grid">${items.length?items.map(record=>`<article class="card resource"><span class="tag">${e(record.subject)}</span><h3>${e(record.title)}</h3><p>${e(record.description||'Audio lecture recording')}</p><div class="actions"><button class="btn primary" data-play-recording="${e(record.id)}" aria-pressed="false">${copyHTML("app.b3b60a22a04f")}</button></div></article>`).join(''):empty(copyRaw("app.be97c581947c"),backend.user()?copyRaw("app.29c42db85672"):copyRaw("app.bd69124b8a83"),backend.user()?'':button(copyRaw("app.c189840cf7e2"),'login','primary'))}</div>`;}

function cases(){const a=filtered(list('cases'));return heading(copyRaw("app.f01913813382"),copyRaw("app.9263860065f1"),button(copyRaw("app.4e4955d2cc5b"),'studio','primary'))+toolbar('cases')+`<div id="results" class="grid">${a.length?a.map(c=>`<article class="card resource"><span class="tag">${e(c.subject)}</span><h3>${e(c.title||c.name)}</h3><p>${e(c.citation||c.description||'Personal case brief')}</p><div class="actions"><button class="btn primary" data-open-case="${e(c.id)}">${copyHTML("app.bfcdf8f8ed0f")}</button><button class="btn" data-bookmark="${e(c.id)}">${store.get().bookmarks.includes(c.id)?copyRaw("app.9ec0cf9f6e73"):copyRaw("app.1509f561f241")}</button></div></article>`).join(''):empty(copyRaw("app.1465cac14901"),copyRaw("app.a40d738af882"),button(copyRaw("app.a2b78491b291"),'studio'))}</div>`;}
function quizPage(){if(quiz?.finished)return resultsPage();if(quiz)return activeQuiz();return heading(copyRaw("app.aa2084088187"),copyRaw("app.db8320521b75"))+`<div class="notice">${copyHTML("app.2f0eee355128")}</div><div class="grid">${list('quizSets').map(q=>{const count=list('quizQuestions').filter(x=>x.quiz_set_id===q.id).length;return `<article class="card resource"><div class="resource-top"><span class="tag">${e(q.subject||'General')}</span><span class="pill">${e(q.difficulty||'Practice')}</span></div><h3>${e(q.name)}</h3><p>${e(q.description||'A focused revision challenge.')}</p><p>${count} ${copyHTML("app.17d5efa695de")} <span class="dot">·</span> ${Number(q.time_minutes)||10} ${copyHTML("app.90e63d85fa1a")}</p><div class="actions"><button class="btn primary" data-start-quiz="${e(q.id)}" ${!count?'disabled':''}>${copyHTML("app.53b467b6192a")}</button></div></article>`;}).join('')}</div>`;}
function time(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function openQuizSetup(id){
 const set=list('quizSets').find(q=>q.id===id),owner=backend.user()?.id;if(!set||!owner)return;
 if(quiz&&!quiz.finished){toast(copyRaw('quizSetup.active'));return;}
 const available=list('quizQuestions').filter(q=>q.quiz_set_id===set.id).length;if(!available){toast(copyRaw('quizSetup.empty'));return;}
 const defaultMinutes=Math.max(1,Math.min(180,Math.round(Number(set.time_minutes)||10)));
 modal(copyRaw('quizSetup.title'),`<p><strong>${e(set.name)}</strong></p><p class="muted">${available} ${copyHTML('quizSetup.available')}</p><form id="quiz-setup-form"><label for="quiz-question-count">${copyHTML('quizSetup.count')}</label><input id="quiz-question-count" name="question_count" type="number" min="1" max="${available}" step="1" value="${available}" required><label for="quiz-time-minutes">${copyHTML('quizSetup.time')}</label><input id="quiz-time-minutes" name="time_minutes" type="number" min="1" max="180" step="1" value="${defaultMinutes}" required><p class="muted">${copyHTML('quizSetup.help')}</p><p id="quiz-setup-status" role="status"></p><div class="actions"><button class="btn primary" id="quiz-setup-start" type="submit">${copyHTML('quizSetup.begin')}</button><button class="btn" id="quiz-setup-cancel" type="button">${copyHTML('quizSetup.cancel')}</button></div></form>`);
 $('#quiz-setup-cancel').onclick=()=>$('#dialog').close();let started=false;
 $('#quiz-setup-form').onsubmit=event=>{
  event.preventDefault();if(started)return;
  try{
   if(backend.user()?.id!==owner)throw new Error(copyRaw('quizSetup.accountChanged'));
   if(quiz&&!quiz.finished)throw new Error(copyRaw('quizSetup.active'));
   const bank=list('quizQuestions').filter(q=>q.quiz_set_id===set.id),options=validateQuizSetup($('#quiz-question-count').value,$('#quiz-time-minutes').value,bank.length);
   const previous=lastQuizOrders.get(set.id)||store.get().attempts.filter(a=>a.quiz_set_id===set.id).at(-1)?.question_order||[],questions=selectQuizQuestions(bank,options.questionCount,previous);
   started=true;lastQuizOrders.set(set.id,questions.map(q=>q.id));quiz={set,questions,time_minutes:options.timeMinutes,index:0,answers:[],end:Date.now()+options.timeMinutes*60000,finished:false};
   $('#dialog').close();clearInterval(quizTimer);quizTimer=setInterval(()=>{if(!quiz||quiz.finished)return;const left=Math.max(0,Math.ceil((quiz.end-Date.now())/1000));if($('#quiz-clock'))$('#quiz-clock').textContent=time(left);if(!left)finishQuiz();},500);render();
  }catch(err){$('#quiz-setup-status').textContent=err.message;}
 };
}
function activeQuiz(){const q=quiz.questions[quiz.index];return heading(e(quiz.set.name),copyRaw("app.e8aa91719407"))+`<section class="card quiz"><div class="card-head"><span class="pill">${copyHTML("app.289aff12b042")} ${quiz.index+1} ${copyHTML("app.28391d3bc64e")} ${quiz.questions.length}</span><span class="tag" id="quiz-clock">${time(Math.max(0,Math.ceil((quiz.end-Date.now())/1000)))}</span></div><div class="progress-track"><span style="width:${(quiz.index+1)/quiz.questions.length*100}%"></span></div><h2 class="question">${e(q.question)}</h2>${q.options.map((o,i)=>`<button class="option ${quiz.answers[quiz.index]===i?'selected':''}" data-answer="${i}" ${quiz.advancing?'disabled':''} aria-pressed="${quiz.answers[quiz.index]===i}"><span>${'ABCD'[i]}</span>${e(o)}</button>`).join('')}<div class="actions"><button class="btn" id="quiz-prev" ${!quiz.index?'disabled':''}>${copyHTML("app.435567b14289")}</button>${quiz.index<quiz.questions.length-1?`<button class="btn primary" id="quiz-next">${copyHTML("app.aa0a618a2a19")}</button>`:`<button class="btn primary" id="quiz-finish">${copyHTML("app.13a0750daa58")}</button>`}<button class="text-button" id="quiz-exit">${copyHTML("app.db8c6b08ac49")}</button></div></section>`;}
async function finishQuiz(){if(!quiz||quiz.finished)return;clearInterval(quizTimer);quiz.finished=true;quiz.score=quiz.questions.filter((q,i)=>Number(q.correct_index)===quiz.answers[i]).length;const a={id:crypto.randomUUID(),quiz_set_id:quiz.set.id,name:quiz.set.name,score:quiz.score,total_questions:quiz.questions.length,question_order:quiz.questions.map(q=>q.id),time_minutes:quiz.time_minutes,date:new Date().toISOString()};store.update({attempts:[...store.get().attempts,a]});render();if(backend.user()&&!String(a.quiz_set_id).startsWith('local-')&&a.quiz_set_id!=='orientation'){try{await backend.saveQuizAttempt(a,Boolean(remote.quizSets?.find(s=>s.id===a.quiz_set_id)?.lexamah_cloud));toast(copyRaw("app.32e43ff763ed"));}catch(err){toast(`${copyRaw("app.7bedcdb3e54d")}${err.message}`);}}}
function resultsPage(){return heading(copyRaw("app.9b880df3daf6"),copyRaw("app.e99ca54f2e23"))+`<section class="card quiz"><span class="eyebrow">${copyHTML("app.accb92f494f9")}</span><div class="score">${quiz.score}<span class="muted"> / ${quiz.questions.length}</span></div><p class="muted">${Math.round(quiz.score/quiz.questions.length*100)}${copyHTML("app.2576bdd5e123")}</p><div class="actions"><button class="btn primary" id="quiz-reset">${copyHTML("app.2647dde46ed7")}</button>${button(copyRaw("app.c2e39c2cee78"),'progress')}</div>${quiz.questions.map((q,i)=>`<div class="review"><strong>${i+1}. ${e(q.question)}</strong><p class="${quiz.answers[i]===Number(q.correct_index)?'correct':'incorrect'}">${copyHTML("app.adceb15c665f")} ${e(q.options[quiz.answers[i]]||'Not answered')}</p><p>${copyHTML("app.4d659fb1085d")} ${e(q.options[Number(q.correct_index)])}</p><p class="muted">${e(q.explanation||'Review this question with your course materials.')}</p></div>`).join('')}</section>`;}
function study(){return heading(copyRaw("app.f7b507002f74"),copyRaw("app.5373074bdf2a"))+`<section class="card timer-card"><span class="eyebrow">${copyHTML("app.39db79e1a524")}</span><h2 style="font:30px var(--serif);margin:20px">${copyHTML("app.1bcdab1477a5")}</h2><label for="focus-subject">${copyHTML("app.c4b89c1f5a03")}</label><select id="focus-subject" ${focusRunning?'disabled':''}>${subjectCatalog.options(focusRunning?focusSubject:'').map(s=>`<option ${s===focusSubject?'selected':''}>${e(s)}</option>`).join('')}</select><div class="timer" id="focus-clock">${time(focusRemaining)}</div><div class="timer-status" id="focus-status">${focusRunning?copyRaw("app.44cdab3e42d7"):copyRaw("app.461d4b5d9342")}</div><div class="actions"><button class="btn primary" id="focus-toggle" ${!focusSubject?'disabled':''}>${focusRunning?copyRaw("app.9a26360a93ea"):copyRaw("app.b1c52ee3677d")}</button><button class="btn" id="focus-reset">${copyHTML("app.daee7606b339")}</button><button class="btn" id="focus-end">${copyHTML("app.b2e6505a803a")}</button></div><label for="focus-length">${copyHTML("app.c0c996d9022f")}</label><select id="focus-length" ${focusRunning?'disabled':''}>${[15,25,45].map(n=>`<option value="${n}" ${focusSeconds===n*60?'selected':''}>${n} ${copyHTML("app.90e63d85fa1a")}</option>`).join('')}</select><p class="muted" style="margin-top:30px">${copyHTML("app.2c96905d3b97")}</p></section>`;}
function saveFocus(){const elapsed=Math.min(focusSeconds,focusSeconds-focusRemaining);if(elapsed<60){toast(copyRaw("app.754931eb5601"));return;}clearInterval(focusTimer);focusRunning=false;store.update({sessions:[...store.get().sessions,{id:crypto.randomUUID(),subject:focusSubject,minutes:Math.floor(elapsed/60),date:new Date().toISOString()}]});focusRemaining=focusSeconds;toast(copyRaw("app.96c3197687ba"));render();}
